WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_s_multi_group'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多组轮换', 'kp-eng-s-multi-group', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多组轮换"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "不仅是单人轮流，而是A组、B组、甚至ABC三组进行错位轮流。核心依然是“打包”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目如：“三台机器 A,B,C。先AB合作1小时，再BC合作1小时，再AC合作1小时，不断循环”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "不要被表面的复杂组合吓到，把它看成一个黑盒大周期。"}]}, {"type": "katexBlock", "attrs": {"content": "\\text{一个完整周期内，A、B、C 各自参与了多少时间？直接汇总！}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[赋总量, 出各单体效率] --> B[分析题干定义的一个完整轮次长什么样]\nB --> C[统计在一轮中, A工作了多久, B工作了多久, C工作了多久]\nC --> D[一轮总产出 = Pa*Ta + Pb*Tb + Pc*Tc]\nD --> E[总工程量 ÷ 一轮总产出 = 轮数 ... 余数]\nE --> F[对着题目定义的顺序, 消化余数]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导模型"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "比如周期是：AB合作1天 -> BC合作1天 -> CA合作1天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "一个周期总共是 3 天。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "在这 3 天里，我们不用管谁和谁配对。只需要看：A 参与了 2 天，B 参与了 2 天，C 参与了 2 天！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "所以一周期总产出 = 2×Pa + 2×Pb + 2×Pc = 2 × (Pa+Pb+Pc)。极其简单！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死扣组合效率：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "很多同学去算 Pa+Pb 等于几，Pb+Pc 等于几，这属于陷入了命题人的障眼法。在评估一整个周期的产出时，组合形态毫无意义，只有【单体在这个周期内的累计出勤时间】才决定产出！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "看到这种花里胡哨的组合轮换，直接在草稿纸上写 A()天，B()天，C()天，填上数字，世界瞬间清静。"}]}]}$$ AS jsonb), NULL, '多组轮换的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "多组轮换"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_s_multi_group", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
